<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {RefreshCw,FolderOpen,Search,List,LayoutGrid} from 'lucide-svelte';
 import FileIcon from './FileIcon.svelte';
 import FilesDelete,{type DeleteResult} from './FilesDelete.svelte';
 import FilesShare from './FilesShare.svelte';
 import FilesFolder from './FilesFolder.svelte';
 import FilesUpload from './FilesUpload.svelte';
 import FileResults from './FileResults.svelte';
 import {mergeFiles,fileLocation,fileSize,fileDate,fileKind,sortFiles,filterFiles,fileFilters,type DriveItem,type FilesPage} from './files';
 let {ownId,isLive,initialItem=null,chats=[],detailsOpen=true,onShowDetails=()=>{},onNavigationHandled=()=>{}}:{ownId:string;isLive:boolean;initialItem?:DriveItem|null;chats?:{id:string;name:string}[];detailsOpen?:boolean;onShowDetails?:()=>void;onNavigationHandled?:()=>void}=$props();
 let selection=$state<string[]>([]),anchor=$state(''),deleteBusy=$state(false),deleteResults=$state<DeleteResult[]>([]),deleteUncertain=$state(false);
 let shareBusy=$state(false);
 let uploadBusy=$state(false),folderBusy=$state(false);
 let rows=$state<DriveItem[]>([]),next=$state<string|null>(null),busy=$state(false),error=$state(''),query=$state(''),applied=$state(''),sort=$state('name'),selected=$state('');
 function savedView():'list'|'icons'{try{return localStorage.getItem('taut.files.view.v1')==='icons'?'icons':'list';}catch{return 'list';}}
 let view=$state<'list'|'icons'>(savedView()),filter=$state('all');
 $effect(()=>{try{localStorage.setItem('taut.files.view.v1',view);}catch{}});
 let trail=$state<{id:string|null;name:string}[]>([{id:null,name:'My OneDrive'}]);let alive=true,serial=0;
 $effect(()=>{const visible=new Set(sorted.map(item=>item.id));const kept=selection.filter(id=>visible.has(id));if(kept.length!==selection.length)selection=kept;});
 function toggle(item:DriveItem,shift:boolean){if(item.shortcut)return;onShowDetails();const ids=sorted.filter(item=>!item.shortcut).map(item=>item.id);if(shift&&ids.includes(anchor)){const a=ids.indexOf(anchor),b=ids.indexOf(item.id);selection=[...new Set([...selection,...ids.slice(Math.min(a,b),Math.max(a,b)+1)])].slice(0,100);}else{selection=selection.includes(item.id)?selection.filter(id=>id!==item.id):[...selection,item.id].slice(0,100);}anchor=item.id;}
 function deleted(results:DeleteResult[]){deleteResults=results;const gone=new Set(results.filter(r=>r.status==='deleted').map(r=>r.id));const covered=results.filter(r=>r.status==='covered');for(let pass=0;pass<results.length;pass++)for(const r of covered)if(r.coveredBy&&gone.has(r.coveredBy))gone.add(r.id);rows=rows.filter(item=>!gone.has(item.id));selection=selection.filter(id=>!gone.has(id));deleteUncertain=results.some(r=>r.status==='unconfirmed');}
 const selectedItems=$derived(rows.filter(item=>selection.includes(item.id)));
 const sorted=$derived(sortFiles(filterFiles(rows,filter),sort));
 async function load(more=false){if(deleteBusy||shareBusy)return;if(!more){selection=[];anchor='';}const version=++serial;busy=true;error='';try{const result=await invoke<FilesPage>('files_page',{query:{folder:applied?null:trail.at(-1)!.id,search:applied||null,next:more?next:null}});if(!alive||version!==serial)return;rows=more?mergeFiles(rows,result.value):result.value;next=result.next;deleteUncertain=false;}catch(e){if(alive&&version===serial)error=String(e);}finally{if(alive&&version===serial)busy=false;}}
 function navigate(index:number){trail=trail.slice(0,index+1);applied='';query='';rows=[];next=null;selected='';void load();}
 function locate(item:DriveItem){if(item.shortcut){error='This is a shared shortcut. Use Open to view it in OneDrive.';return;}if(item.folder){trail=applied?[trail[0],{id:item.id,name:item.name}]:[...trail,{id:item.id,name:item.name}];applied='';query='';rows=[];next=null;selected='';void load();}else{selected=item.id;selection=[item.id];anchor=item.id;onShowDetails();}}
 function search(){applied=query.trim();rows=[];next=null;selected='';void load();}
 onMount(()=>{if(initialItem){const item=initialItem;const id=item.folder?item.id:item.parentId;if(id)trail=[trail[0],{id,name:item.folder?item.name:fileLocation(item).split('/').filter(Boolean).at(-1)||'Containing folder'}];selected=item.id;onNavigationHandled();}if(isLive)void load();});
 onDestroy(()=>{alive=false;serial++;});
</script>
<section class="files-workspace" aria-label="Files"><header><div><div class="eyebrow">YOUR FILES, WITHIN REACH</div><h1>Files</h1><p>Browse your OneDrive. Downloads are saved only where you choose.</p></div><button aria-label="Refresh OneDrive" disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy||!isLive} onclick={()=>load()}><RefreshCw size={18}/></button></header>
<div class="toolbar"><nav aria-label="OneDrive folders">{#each trail as folder,i}<button disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy} aria-current={!applied&&i===trail.length-1?'page':undefined} onclick={()=>navigate(i)}>{folder.name}</button>{#if i<trail.length-1}<span>/</span>{/if}{/each}</nav><form onsubmit={event=>{event.preventDefault();search();}}><Search size={15}/><input aria-label="Search OneDrive" bind:value={query} maxlength="500" placeholder="Search all of My OneDrive"/><button disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy||!isLive}>Search</button></form></div>
<div class="workspace-body"><div class="contents">{#if !isLive}<p>Connect Microsoft 365 to browse your OneDrive.</p>{:else}
 {#if applied}<h2>OneDrive results for “{applied}”</h2><button onclick={()=>navigate(trail.length-1)} disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy}>Back to folder</button>{/if}
 <FilesFolder {ownId} folder={trail.at(-1)!.id} destination={trail.map(folder=>folder.name).join(' / ')} disabled={!!applied||busy||uploadBusy||deleteBusy||shareBusy} onCreated={()=>void load()} onBusyChange={value=>folderBusy=value}/>
 <FilesUpload {ownId} folder={trail.at(-1)!.id} destination={trail.map(folder=>folder.name).join(' / ')} disabled={!!applied||busy||folderBusy||deleteBusy||shareBusy} existingNames={rows.map(item=>item.name)} onUploaded={()=>void load()} onBusyChange={value=>uploadBusy=value}/>
 <div class="list-heading"><span>{filter==='all'?`${rows.length} items loaded`:`${sorted.length} of ${rows.length} loaded items shown`}{next?' · more available':''}</span><div class="file-controls"><div class="views" role="group" aria-label="Files view"><button aria-label="List view" aria-pressed={view==='list'} onclick={()=>view='list'}><List size={16}/><span>List</span></button><button aria-label="Icons view" aria-pressed={view==='icons'} onclick={()=>view='icons'}><LayoutGrid size={16}/><span>Icons</span></button></div><label>Filter loaded items<select aria-label="Filter loaded items" disabled={deleteBusy} bind:value={filter}>{#each fileFilters as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Sort loaded items<select aria-label="Sort loaded items" disabled={deleteBusy} bind:value={sort}><option value="name">Name A–Z</option><option value="modified">Recently modified</option><option value="created">Recently added</option></select></label></div></div>
 {#if error}<p role="alert">{error}</p><button disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy} onclick={()=>load(!!rows.length&&!!next)}>Try again</button>{/if}
 <div class="selection-bar" role="group" aria-label="File selection"><button disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy} onclick={()=>{onShowDetails();selection=sorted.filter(item=>!item.shortcut).slice(0,100).map(item=>item.id);}}>Select all loaded items</button><span>Choose files or folders to see details and actions.</span></div>
 {#if sorted.filter(item=>!item.shortcut).length>100}<p class="hint">Up to 100 items can be selected at a time.</p>{/if}
 {#if deleteResults.length}<div role="status"><p>{deleteResults.filter(r=>r.status==='deleted').length} moved to Recycle Bin{deleteResults.some(r=>r.status==='covered')?' · nested selections are covered by their selected folder':''}.</p>{#each deleteResults.filter(r=>r.status==='failed'||r.status==='unconfirmed') as result}<p>{rows.find(item=>item.id===result.id)?.name||'Selected item'}: {result.error}</p>{/each}</div>{/if}
 <FileResults selection={selection} onToggle={toggle} selectionDisabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy} {view} items={sorted} {ownId} {selected} onLocate={locate} search={!!applied}/>
 {#if busy}<p role="status">Loading OneDrive…</p>{:else if !rows.length&&!error}<div class="empty"><FolderOpen size={40}/><h2>{applied?'No matching files':'This folder is empty'}</h2></div>{/if}
 {#if !busy&&rows.length&&!sorted.length}<p>No loaded items match this type.{next?' Load more files to check additional items.':''}</p>{/if}
 {#if next}<button class="more" disabled={busy||uploadBusy||folderBusy||deleteBusy||shareBusy} onclick={()=>load(true)}>Load more files</button>{/if}<p class="hint">Downloads up to 100 MB. Larger files and shared shortcuts can be opened in OneDrive. In-app previews are coming later.</p>
{/if}</div>
{#if detailsOpen}<aside class="selection-panel" aria-label="Selection details">
 <div class="panel-heading"><div class="eyebrow">WITHIN REACH</div><h2>Selection details</h2><span>{selection.length} selected</span></div>
 <div class="panel-actions">
  <div class="action primary"><FilesShare {ownId} {chats} items={selectedItems} disabled={!selection.length||selection.length>5||busy||uploadBusy||folderBusy||deleteBusy||shareBusy||!isLive} onBusyChange={value=>shareBusy=value}/></div>
  <div class="action"><FilesDelete {ownId} items={selectedItems} disabled={!selection.length||busy||uploadBusy||folderBusy||deleteBusy||shareBusy||deleteUncertain||!isLive} onResults={deleted} onBusyChange={value=>deleteBusy=value}/></div>
  <button disabled={!selection.length||deleteBusy||shareBusy} onclick={()=>{selection=[];selected='';}}>Clear selection</button>
 </div>
 {#if selection.length>5}<p class="panel-hint">Share up to 5 files or folders at a time.</p>{/if}
 <div class="selected-list">{#if selectedItems.length}
  <ul aria-label="Selected files and folders">{#each selectedItems as item(item.id)}<li><FileIcon {item} size={24}/><div class="selected-copy"><strong>{item.name}</strong><small>{fileKind(item).label}{item.folder?'':` · ${fileSize(item.size)}`}</small>{#if applied}<small>{fileLocation(item)}</small>{/if}{#if selectedItems.length===1}<small>Modified {fileDate(item.modified)}</small>{/if}</div><button class="remove-selected" aria-label={`Deselect ${item.name}`} title="Remove from selection" disabled={deleteBusy||shareBusy||busy||uploadBusy||folderBusy} onclick={()=>{selection=selection.filter(id=>id!==item.id);if(selected===item.id)selected='';}}>×</button></li>{/each}</ul>
  {#if selectedItems.some(item=>item.folder)}<p class="panel-hint">Folder sharing and deletion include the contents. You’ll review the action before anything changes.</p>{/if}
 {:else}<div class="selection-empty"><FolderOpen size={32}/><h3>A little context.</h3><p>Select files or folders to keep their names and actions here while you browse.</p></div>{/if}</div>
</aside>{/if}</div></section>
<style>
.workspace-body{display:flex;flex:1;min-height:0;min-width:0;overflow:hidden;container-type:inline-size}.contents{min-width:0}.selection-panel{width:300px;flex:none;min-height:0;display:flex;flex-direction:column;background:var(--surface-panel);border-left:1px solid var(--border)}.panel-heading{padding:22px 20px 16px;flex:none}.panel-heading h2{margin:8px 0 10px;font-size:20px}.panel-heading>span{font-size:12px;color:var(--text-secondary)}.panel-actions{display:grid;gap:8px;padding:0 20px 18px;flex:none}.action> :global(button){width:100%;padding:11px 12px;border:1px solid var(--border-strong);border-radius:8px;font-size:13px}.action.primary> :global(button){background:var(--accent);border-color:var(--accent);color:var(--text-on-accent)}.panel-actions>button{font-size:12px}.selected-list{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:0 20px 20px}.selected-list ul{padding:0;margin:0;list-style:none}.selected-list li{display:flex;align-items:flex-start;gap:10px;padding:15px 0;border-top:1px solid var(--border)}.selected-copy{flex:1;min-width:0}.selected-copy strong{display:block;font-size:13px;line-height:1.5;overflow-wrap:anywhere}.selected-copy small{display:block;font-size:11px;color:var(--text-secondary);line-height:1.6;margin-top:4px;overflow-wrap:anywhere}.remove-selected{flex:none;padding:0;width:26px;height:26px;font-size:18px;color:var(--text-secondary);border-color:transparent}.remove-selected:hover{background:var(--surface-hover);color:var(--text-primary)}.panel-hint{padding:0 20px;font-size:11px;line-height:1.7;color:var(--text-secondary)}.selected-list .panel-hint{padding:0}.selection-empty{padding:22px 0;color:var(--text-secondary)}.selection-empty h3{font-size:16px;color:var(--text-primary)}.selection-empty p{font-size:12px;line-height:1.8}.selection-bar>span{color:var(--text-secondary);font-size:11px}
@container(max-width:850px){.selection-panel{width:260px}.contents{padding:20px!important}.panel-heading{padding:18px 16px 12px}.panel-actions{padding:0 16px 14px}.selected-list{padding:0 16px 16px}}
@media(max-width:700px){.workspace-body{flex-direction:column}.selection-panel{width:auto;max-height:48%;border-left:0;border-top:1px solid var(--border)}.panel-heading{padding:10px 16px;display:flex;align-items:center;justify-content:space-between;gap:10px}.panel-heading .eyebrow{display:none}.panel-heading h2{font-size:15px;margin:0}.panel-actions{grid-template-columns:repeat(3,minmax(0,1fr));padding:0 16px 10px;gap:6px}.action> :global(button),.panel-actions>button{font-size:11px;padding:8px;min-height:36px}.selected-list{padding:0 16px 8px}.selected-list li{padding:10px 0}.selection-empty{padding:0}.selection-empty h3,.selection-empty> :global(svg){display:none}.selection-empty p{margin:4px 0}}

.selection-bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0;font-size:12px}
.file-controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.views{display:flex;gap:4px}.views button{display:flex;align-items:center;gap:6px;font-size:12px}.views button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}.list-heading{flex-wrap:wrap}
.files-workspace{flex:1;min-width:0;min-height:0;overflow:hidden;display:flex;flex-direction:column;color:var(--text-primary)}header{display:flex;justify-content:space-between;align-items:center;padding:28px;border-bottom:1px solid var(--border);background:var(--surface-panel)}h1{margin:8px 0;font-size:28px}header p{font-size:12px;color:var(--text-secondary)}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent);font-weight:700}button,select,input{font:inherit;color:var(--text-primary)}button{cursor:pointer;padding:8px 12px;border:1px solid var(--border-strong);border-radius:7px}button:disabled{opacity:.5;cursor:default}.toolbar{display:flex;gap:16px;flex-wrap:wrap;justify-content:space-between;padding:16px 28px;border-bottom:1px solid var(--border)}nav{display:flex;align-items:center;gap:8px;flex-wrap:wrap}nav button{font-size:12px;color:var(--accent)}form{display:flex;align-items:center;gap:8px}input,select{min-width:0;border:1px solid var(--border-strong);background:var(--surface-panel);padding:8px;border-radius:6px;font-size:12px}.contents{padding:24px 28px;overflow:auto;flex:1;min-height:0}.list-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px;font-size:12px;color:var(--text-secondary)}label{display:flex;gap:8px;align-items:center}.hint{font-size:11px;line-height:1.7;color:var(--text-secondary);margin-top:20px}.empty{text-align:center;padding:50px;color:var(--text-secondary)}.more{margin-top:18px}[role=alert]{color:var(--error)}h2{font-size:18px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}</style>
